import { Match as M, Option, Schema as S } from "effect";
import { Command, Submodel, Subscription } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as DragAndDrop from "../../ui/drag-and-drop";

// MODEL

const Task = S.Struct({
  id: S.String,
  label: S.String,
});

export const Model = S.Struct({
  dragAndDrop: DragAndDrop.Model,
  tasks: S.Array(Task),
  status: S.String,
});

export type Model = typeof Model.Type;

// MESSAGE

export const GotDragAndDropMessage = m("GotDragAndDropMessage", {
  message: DragAndDrop.Message,
});

export const Message = S.Union([GotDragAndDropMessage]);
export type Message = typeof Message.Type;

// INIT

const orderStatus = (tasks: readonly (typeof Task.Type)[]): string =>
  `Task order: ${tasks.map((task) => task.label).join(", ")}`;

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => {
  const [dragAndDrop, commands] = DragAndDrop.init({
    id: "drag-and-drop-basic",
  });
  const tasks = [
    { id: "plan", label: "Plan" },
    { id: "build", label: "Build" },
    { id: "verify", label: "Verify" },
  ];

  return [
    {
      dragAndDrop,
      tasks,
      status: orderStatus(tasks),
    },
    Command.mapMessages(commands, (message) =>
      GotDragAndDropMessage({ message })
    ),
  ];
};

// UPDATE

const reorderTasks = (
  tasks: readonly (typeof Task.Type)[],
  fromIndex: number,
  toIndex: number
): readonly (typeof Task.Type)[] => {
  const task = tasks[fromIndex];

  if (task === undefined) {
    return tasks;
  }

  const withoutTask = tasks.filter((_, index) => index !== fromIndex);
  const boundedTargetIndex = Math.max(0, Math.min(toIndex, withoutTask.length));

  return [
    ...withoutTask.slice(0, boundedTargetIndex),
    task,
    ...withoutTask.slice(boundedTargetIndex),
  ];
};

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotDragAndDropMessage: ({ message }) => {
        const [dragAndDrop, commands, maybeOutMessage] = DragAndDrop.update(
          model.dragAndDrop,
          message
        );

        const tasks = Option.match(maybeOutMessage, {
          onNone: () => model.tasks,
          onSome: M.type<DragAndDrop.OutMessage>().pipe(
            M.tagsExhaustive({
              Reordered: ({ fromIndex, toIndex }) =>
                reorderTasks(model.tasks, fromIndex, toIndex),
              Cancelled: () => model.tasks,
            })
          ),
        });

        return [
          evo(model, {
            dragAndDrop: () => dragAndDrop,
            tasks: () => tasks,
            status: () => orderStatus(tasks),
          }),
          Command.mapMessages(commands, (message) =>
            GotDragAndDropMessage({ message })
          ),
        ];
      },
    })
  );

export const subscriptions = Subscription.lift(DragAndDrop.subscriptions)<
  Model,
  Message
>({
  toChildModel: (model) => model.dragAndDrop,
  toParentMessage: (message) => GotDragAndDropMessage({ message }),
});

// VIEW

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("space-y-3")],
    [
      DragAndDrop.sortableListView({
        model: model.dragAndDrop,
        containerId: "tasks",
        items: model.tasks,
        label: "Task order",
        status: model.status,
        toParentMessage: (message) => GotDragAndDropMessage({ message }),
      }),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, expect, test } from "vitest";

import * as DragAndDrop from "../../ui/drag-and-drop";
import * as DragAndDropBasicExample from "./main";

describe("DragAndDrop Basic example", () => {
  test("renders functional sortable attributes", () => {
    Scene.scene(
      {
        update: DragAndDropBasicExample.update,
        view: DragAndDropBasicExample.view,
      },
      Scene.with(DragAndDropBasicExample.init()[0]),
      Scene.expect(Scene.role("listbox", { name: "Task order" })).toHaveAttr(
        "data-droppable-id",
        "tasks"
      ),
      Scene.expect(Scene.role("option", { name: /Plan/u })).toHaveAttr(
        "data-draggable-id",
        "plan"
      ),
      Scene.expect(Scene.role("option", { name: /Plan/u })).toHaveHandler(
        "pointerdown"
      ),
      Scene.expect(Scene.role("option", { name: /Plan/u })).toHaveHandler(
        "keydown"
      ),
      Scene.keydown(Scene.role("option", { name: /Plan/u }), " "),
      Scene.expect(Scene.role("option", { name: /Plan/u })).toHaveAttr(
        "data-keyboard-dragging",
        ""
      )
    );
  });

  test("applies keyboard reorder through the real drag lifecycle", () => {
    const [initialModel] = DragAndDropBasicExample.init();
    const [activatedModel] = DragAndDropBasicExample.update(
      initialModel,
      DragAndDropBasicExample.GotDragAndDropMessage({
        message: DragAndDrop.ActivatedKeyboardDrag({
          itemId: "plan",
          containerId: "tasks",
          index: 0,
        }),
      })
    );
    const [movingModel, movingCommands] = DragAndDropBasicExample.update(
      activatedModel,
      DragAndDropBasicExample.GotDragAndDropMessage({
        message: DragAndDrop.PressedArrowKey({ direction: "Down" }),
      })
    );
    const [resolvedModel] = DragAndDropBasicExample.update(
      movingModel,
      DragAndDropBasicExample.GotDragAndDropMessage({
        message: DragAndDrop.ResolvedKeyboardMove({
          targetContainerId: "tasks",
          targetIndex: 1,
        }),
      })
    );
    const [droppedModel, droppedCommands] = DragAndDropBasicExample.update(
      resolvedModel,
      DragAndDropBasicExample.GotDragAndDropMessage({
        message: DragAndDrop.ConfirmedKeyboardDrop(),
      })
    );

    expect(movingCommands).toHaveLength(1);
    expect(movingCommands[0]?.name).toBe("ResolveKeyboardMove");
    expect(movingCommands[0]?.args).toEqual({
      itemId: "plan",
      currentContainerId: "tasks",
      currentIndex: 0,
      direction: "Down",
    });
    expect(droppedCommands).toHaveLength(1);
    expect(droppedCommands[0]?.name).toBe("FocusItem");
    expect(droppedCommands[0]?.args).toEqual({ itemId: "plan" });

    Scene.scene(
      {
        update: DragAndDropBasicExample.update,
        view: DragAndDropBasicExample.view,
      },
      Scene.with(droppedModel),
      Scene.expect(Scene.text("Task order: Build, Plan, Verify")).toExist()
    );
  });
});
